import{memberEngagement,promotionTiming,signupEngagement,recentFormat}from'../analytics/engagement.js';
import{assessDataset}from'../analytics/data-quality.js';import{attendanceMetrics,attendanceTrend,compareRecent,compareCategories,attendanceAnomalies}from'../analytics/attendance.js';import{analyzeRetention}from'../analytics/retention.js';import{socialReach,conversionRates,promotionAnalysis}from'../analytics/promotion.js';import{forecastAttendance}from'../analytics/forecasting.js';import{clubHealth,meetingPulse}from'../analytics/health.js';import{strategyAnalysis}from'./strategy-analyst.js';
const trusted=new WeakSet();
export function createContext(rawRows,quality=null){const checked=assessDataset(rawRows);const ctx={rows:checked.rows,quality:quality??checked.quality,cache:new Map()};trusted.add(ctx);return ctx}
const handlers={analyze_member_engagement:c=>memberEngagement(c.rows),analyze_promotion_timing:c=>promotionTiming(c.rows),analyze_signup_engagement:c=>signupEngagement(c.rows),compare_recent_formats:c=>recentFormat(c.rows),validate_dataset:c=>c.quality,summarize_dataset:c=>({sampleSize:c.rows.length,dateFrom:c.rows.map(r=>r.date).sort()[0]??null,dateTo:c.rows.map(r=>r.date).sort().at(-1)??null,fields:Object.fromEntries(['type','time','promotion','reach','signups','members'].map(k=>[k,c.rows.filter(r=>r[k]!=null).length]))}),calculate_attendance_metrics:c=>attendanceMetrics(c.rows),calculate_attendance_trend:(c,p)=>attendanceTrend(c.rows,p),compare_recent_period:(c,p)=>compareRecent(c.rows,p),compare_meeting_types:c=>compareCategories(c.rows,'type',analyzeRetention(c.rows)),compare_timing:c=>({time:compareCategories(c.rows,'time'),weekday:compareCategories(c.rows,'weekday')}),compare_promotion_channels:c=>promotionAnalysis(c.rows,analyzeRetention(c.rows)),analyze_social_reach:c=>socialReach(c.rows),calculate_conversion_rate:c=>conversionRates(c.rows),calculate_retention:c=>analyzeRetention(c.rows),detect_attendance_anomalies:c=>attendanceAnomalies(c.rows),forecast_attendance:(c,p)=>forecastAttendance(c.rows,p),compare_prediction_to_actual:(c,p)=>meetingPulse(c.rows,p),generate_club_health_summary:c=>clubHealth(c.rows),recommend_next_steps:c=>strategyAnalysis({rows:c.rows,promotionTiming:promotionTiming(c.rows),formats:compareCategories(c.rows,'type'),promotion:promotionAnalysis(c.rows),timing:compareCategories(c.rows,'time'),retention:analyzeRetention(c.rows),attendance:attendanceMetrics(c.rows)})};
export const TOOL_LABELS={analyze_member_engagement:'Returning-attendee participation',analyze_promotion_timing:'Promotion lead time',analyze_signup_engagement:'Pre-meeting signup ratios',compare_recent_formats:'Recent meeting formats',validate_dataset:'Data quality',summarize_dataset:'Dataset summary',calculate_attendance_metrics:'Attendance statistics',calculate_attendance_trend:'Attendance trend',compare_recent_period:'Recent-period comparison',compare_meeting_types:'Meeting formats',compare_timing:'Meeting times and weekdays',compare_promotion_channels:'Promotion channels',analyze_social_reach:'Social reach',calculate_conversion_rate:'Engagement ratios',calculate_retention:'Member retention',detect_attendance_anomalies:'Unusual attendance',forecast_attendance:'Attendance forecast',compare_prediction_to_actual:'Meeting Pulse',generate_club_health_summary:'Club health',recommend_next_steps:'Evidence-based recommendations'};
export const TOOL_NAMES=Object.freeze(Object.keys(handlers));
export function runTool(name,ctx,params={}){if(!trusted.has(ctx))throw Error('Tools require a validated dataset context.');if(!Object.hasOwn(handlers,name))throw Error('Unknown analytical tool.');if(!params||typeof params!=='object'||Array.isArray(params))throw Error('Tool parameters must be an object.');const allowed=name==='forecast_attendance'?['event']:name==='compare_prediction_to_actual'?['meetingId','savedPrediction']:['calculate_attendance_trend','compare_recent_period'].includes(name)?['period','window']:[];if(Object.keys(params).some(k=>!allowed.includes(k)))throw Error('Unsupported tool parameter.');const key=JSON.stringify([name,params]);if(!ctx.cache.has(key))ctx.cache.set(key,handlers[name](ctx,params));return ctx.cache.get(key)}
